//! Raw MuJoCo bindings, generated by `build.rs` with bindgen at compile time
//! into `$OUT_DIR/bindings.rs`. Nothing here is safe to call; `src/sim.rs`
//! wraps what Rookery needs behind the `Sim` facade.
//!
//! The module is `pub(crate)`: no other crate sees a MuJoCo type or symbol,
//! so `unsafe` stays inside `crates/sim` (rule 4). The surface is whatever the
//! allowlist in `build.rs` names; widen it there, not here.
//!
//! ```text
//!   build.rs ──bindgen over mujoco.h──▶ $OUT_DIR/bindings.rs
//!                                              │ include!
//!                                              ▼
//!   ffi::generated (lint allows for C names) ──pub(crate) use *──▶ ffi::*
//! ```

/// The generated items, isolated so that the lint allows the C naming needs
/// (`mjModel`, `mj_step`, `mjVERSION_HEADER`, fields unused until a phase
/// touches them) do not leak onto hand-written code in this file.
mod generated {
    #![allow(
        non_upper_case_globals,
        non_camel_case_types,
        non_snake_case,
        dead_code
    )]
    #![allow(clippy::all)]

    include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
}

pub(crate) use generated::*;

#[cfg(test)]
mod tests {
    use std::ffi::CStr;

    use super::*;

    /// The release pinned in the root `CLAUDE.md` ("Toolchain") and in CI
    /// (`MUJOCO_VERSION`), as MuJoCo encodes it:
    /// `major * 1_000_000 + minor * 1_000 + patch`.
    const PINNED_VERSION: u32 = 3_016_000;
    const PINNED_VERSION_STRING: &str = "3.16.0";

    /// The header bindgen parsed is the pinned release.
    #[test]
    fn header_is_the_pinned_release() {
        assert_eq!(
            mjVERSION_HEADER, PINNED_VERSION,
            "MUJOCO_DIR points at a MuJoCo other than the pinned {PINNED_VERSION_STRING}"
        );
    }

    /// The library the binary actually linked matches the header it was
    /// compiled against (MuJoCo's own `mjVERSION_HEADER` vs `mj_version()`
    /// check). A mismatch means the build found one install and the loader
    /// another.
    #[test]
    fn linked_library_matches_header() {
        // SAFETY: `mj_version` takes no arguments, touches no MuJoCo state and
        // needs no prior initialisation; it returns a compile-time constant.
        let linked = unsafe { mj_version() };
        let header = i32::try_from(mjVERSION_HEADER).expect("mjVERSION_HEADER fits an int");
        assert_eq!(
            linked, header,
            "linked libmujoco reports {linked} but the header says {header}"
        );
    }

    /// Same check in human-readable form, against the version CI downloads.
    #[test]
    fn linked_library_reports_the_pinned_version_string() {
        // SAFETY: `mj_versionString` returns a pointer to a NUL-terminated
        // string in the library's static storage; it is never freed or
        // modified, so reading it here is valid for the process lifetime.
        let version = unsafe { CStr::from_ptr(mj_versionString()) };
        assert_eq!(version.to_str().expect("ASCII"), PINNED_VERSION_STRING);
    }
}
